/* v1.3.16 website updater + winner-focused recent results */
.system-update-card{display:grid;gap:14px}.update-status-row{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.update-release{border:1px solid var(--line);border-radius:18px;padding:14px;background:var(--soft);display:grid;gap:8px}.update-release ul{margin:0;padding-left:20px;display:grid;gap:5px}.update-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}.update-actions form,.update-actions .btn{width:100%}@media(max-width:420px){.update-actions{grid-template-columns:1fr}}
.recent-results{padding:10px}.result-match{display:grid;gap:7px;padding:8px 0}.result-match+.result-match{border-top:1px solid var(--line);margin-top:6px;padding-top:14px}.result-team{display:flex;align-items:center;justify-content:space-between;gap:10px;border:1px solid transparent;border-radius:15px;padding:11px 12px;transition:.15s}.result-team.winner{border-color:rgba(22,163,74,.42);background:rgba(34,197,94,.12);box-shadow:inset 4px 0 0 #16a34a}.result-name{min-width:0;display:flex;align-items:center;gap:8px;flex-wrap:wrap}.winner-tag{font-size:10px;font-weight:900;letter-spacing:.08em;color:#0f6f32;background:rgba(34,197,94,.16);border:1px solid rgba(22,163,74,.28);border-radius:999px;padding:4px 7px}.result-score{font-size:23px;line-height:1;font-weight:950;min-width:30px;text-align:right}.result-team:not(.winner){opacity:.72}body[data-appearance="dark"] .result-team.winner{background:rgba(34,197,94,.14)}body[data-appearance="dark"] .winner-tag{color:#8ff0ab;background:rgba(34,197,94,.12)}
